WITH with_windows AS (SELECT *, AVG(credit_limit) OVER (PARTITION BY country ORDER BY credit_limit, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS credit_limit_avg_3, LAST_VALUE(city) IGNORE NULLS OVER (PARTITION BY country ORDER BY signup_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_city FROM customers) SELECT segment, CASE WHEN age >= 71 THEN 'HIGH' ELSE 'LOW' END AS age_tier, AVG(credit_limit) AS avg_credit_limit, MAX(credit_limit_avg_3) FILTER (WHERE country = 'JP') AS jp_max_credit_limit_avg_3, ROUND(SUM(age) / NULLIF(COUNT(CASE WHEN country = 'UK' THEN 1 END), 0), 2) AS age_per_uk, APPROX_PERCENTILE(credit_limit_avg_3, 0.9) AS credit_limit_avg_3_p90, ROUND(AVG(credit_limit), 2) AS avg_credit_limit_2 FROM with_windows GROUP BY segment, CASE WHEN age >= 71 THEN 'HIGH' ELSE 'LOW' END
